// Proves the bulk-rewritten NFL DvP recompute (lib/historicalQueries.js's
// computeNflDefenseByPositionBulk, 3 reads + 1 txn session) reproduces
// IDENTICAL numbers to the existing sync recompute (lib/nflDvpEngine.js's
// recomputeNflDefenseByPosition, ~640 individual queries), and reports the
// real query-count reduction.
//
// The OLD baseline is generated by spawning scripts/recompute-nfl-dvp.js
// as a SEPARATE process (it uses node:sqlite for the exact same reason
// this test avoids running the ~640-query sync recompute in-process here:
// that write volume was found to reproducibly crash better-sqlite3's
// native binding on this machine -- see lib/historicalStore.js's header
// for the same finding, which is WHY its own SQLite backend was switched
// to node:sqlite too). This keeps the test itself reliable to run
// repeatedly rather than intermittently crashing.
//
//   node scripts/test-bulk-nfl-dvp-parity.js

const { execFileSync } = require('child_process');
const path = require('path');

let failures = 0;
function check(name, condition, detail) {
  if (condition) console.log(`PASS  ${name}`);
  else { failures++; console.log(`FAIL  ${name}${detail ? '  -- ' + detail : ''}`); }
}

(async () => {
  const store = require('../lib/historicalStore');
  const { computeNflDefenseByPositionBulk } = require('../lib/historicalQueries');

  console.log('Running OLD sync recompute as a separate process (baseline, ~640 queries)...');
  const t0 = Date.now();
  const oldStdout = execFileSync(process.execPath, [path.join(__dirname, 'recompute-nfl-dvp.js')], { encoding: 'utf8', timeout: 60000 });
  const oldMs = Date.now() - t0;
  const oldResult = JSON.parse(oldStdout.slice(oldStdout.indexOf('{')));
  const before = await store.query(`SELECT team, position, window_type, pass_attempts_allowed, rush_attempts_allowed, receiving_yards_allowed, fantasy_points_allowed, rank, games_sampled, player_games_sampled FROM nfl_defense_by_position ORDER BY team, position, window_type`);
  console.log(`  old: ${before.length} rows, ${oldMs}ms`);

  console.log('Running NEW bulk recompute (3 reads + 1 txn session)...');
  const t1 = Date.now();
  const bulkResult = await computeNflDefenseByPositionBulk();
  const bulkMs = Date.now() - t1;
  const after = await store.query(`SELECT team, position, window_type, pass_attempts_allowed, rush_attempts_allowed, receiving_yards_allowed, fantasy_points_allowed, rank, games_sampled, player_games_sampled FROM nfl_defense_by_position ORDER BY team, position, window_type`);
  console.log(`  bulk: ${after.length} rows, ${bulkMs}ms, reported query count: ${bulkResult._queryCount} (vs old's ~640 estimated: 5 windows x 4 positions x ~32 teams)`);

  check('1: same row count before/after', before.length === after.length, `${before.length} vs ${after.length}`);
  check('2: every (team,position,window_type) value identical between old sync and new bulk recompute', JSON.stringify(before) === JSON.stringify(after));
  check('3: bulk recompute used a small, fixed query count (<=5), not O(teams x positions x windows)', bulkResult._queryCount <= 5, `actual: ${bulkResult._queryCount}`);
  check('4: current/completeSeasons resolution identical', oldResult.current === bulkResult.current && JSON.stringify(oldResult.completeSeasons) === JSON.stringify(bulkResult.completeSeasons));

  // Spot check per-(position,window) row counts match too (not just aggregate)
  let allCountsMatch = true;
  const mismatches = [];
  for (const key of Object.keys(oldResult)) {
    if (key === 'current' || key === 'completeSeasons') continue;
    if (oldResult[key] !== bulkResult[key]) { allCountsMatch = false; mismatches.push({ key, old: oldResult[key], bulk: bulkResult[key] }); }
  }
  check('5: per-(position,window) row counts identical', allCountsMatch, JSON.stringify(mismatches));

  console.log(`\nQuery-count reduction: ~640 (estimated old) -> ${bulkResult._queryCount} (new bulk) for the same recompute`);
  console.log(`Timing: old=${oldMs}ms bulk=${bulkMs}ms`);
  console.log(`\n${failures === 0 ? 'ALL BULK-NFL-DVP PARITY TESTS PASSED' : `${failures} TEST(S) FAILED`}`);
  const code = failures === 0 ? 0 : 1;
  process.exitCode = code;
  process.exit(code);
})().catch(e => { console.error('FATAL:', e); process.exitCode = 1; process.exit(1); });
